package com.secure.documentwallet;

import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.os.*;import android.print.*;import androidx.core.content.FileProvider;import org.json.*;import java.io.*;import java.util.zip.*;

final class DocumentExporter {
 private final Context c;private final VaultRepository repo;
 DocumentExporter(Context c){this.c=c;repo=new VaultRepository(c);}
 File pdf(JSONObject doc,boolean frontBackOnePage)throws Exception{File out=file(doc,"pdf");JSONArray pages=doc.getJSONArray("pages");PdfDocument pdf=new PdfDocument();try{if(frontBackOnePage&&pages.length()>=2){PdfDocument.Page p=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());byte[] front=repo.page(doc,0);Bitmap frontImage=BitmapFactory.decodeByteArray(front,0,front.length);draw(p.getCanvas(),frontImage,40,70,515,325);frontImage.recycle();byte[] back=repo.page(doc,1);Bitmap backImage=BitmapFactory.decodeByteArray(back,0,back.length);draw(p.getCanvas(),backImage,40,447,515,325);backImage.recycle();pdf.finishPage(p);for(int i=2;i<pages.length();i++)addPdfPage(pdf,doc,i);}else for(int i=0;i<pages.length();i++)addPdfPage(pdf,doc,i);try(OutputStream os=new FileOutputStream(out)){pdf.writeTo(os);}}finally{pdf.close();}return out;}
 private void addPdfPage(PdfDocument pdf,JSONObject doc,int index)throws Exception{byte[] b=repo.page(doc,index);Bitmap image=BitmapFactory.decodeByteArray(b,0,b.length);PdfDocument.Page p=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,index+1).create());draw(p.getCanvas(),image,40,50,515,742);pdf.finishPage(p);image.recycle();}
 private void draw(Canvas c,Bitmap b,int x,int y,int maxW,int maxH){float scale=Math.min((float)maxW/b.getWidth(),(float)maxH/b.getHeight());int w=Math.round(b.getWidth()*scale),h=Math.round(b.getHeight()*scale),left=x+(maxW-w)/2,top=y+(maxH-h)/2;Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);p.setShadowLayer(5,0,2,0x33000000);c.drawBitmap(b,null,new Rect(left,top,left+w,top+h),p);p.clearShadowLayer();p.setStyle(Paint.Style.STROKE);p.setColor(0xffd3d8d6);c.drawRect(left,top,left+w,top+h,p);}
 File docx(JSONObject doc,boolean frontBackOnePage)throws Exception{File out=file(doc,"docx");JSONArray pages=doc.getJSONArray("pages");try(ZipOutputStream z=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(out)))){put(z,"[Content_Types].xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Default Extension=\"jpg\" ContentType=\"image/jpeg\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");put(z,"_rels/.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");StringBuilder rel=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");StringBuilder body=new StringBuilder();for(int i=0;i<pages.length();i++){int n=i+1;byte[] raw=repo.page(doc,i);Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length);ByteArrayOutputStream jpg=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,94,jpg);bitmap.recycle();bytes(z,"word/media/image"+n+".jpg",jpg.toByteArray());rel.append("<Relationship Id=\"rId").append(n).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"media/image").append(n).append(".jpg\"/>");body.append(picture(n,frontBackOnePage&&i<2?4400000:6000000,frontBackOnePage&&i<2?3300000:7600000));if(!(frontBackOnePage&&i==0)&&i<pages.length()-1)body.append("<w:p><w:r><w:br w:type=\"page\"/></w:r></w:p>");}rel.append("</Relationships>");put(z,"word/_rels/document.xml.rels",rel.toString());String xml="<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:pic=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><w:body>"+body+"<w:sectPr><w:pgSz w:w=\"12240\" w:h=\"15840\"/><w:pgMar w:top=\"720\" w:right=\"720\" w:bottom=\"720\" w:left=\"720\"/></w:sectPr></w:body></w:document>";put(z,"word/document.xml",xml);}return out;}
 File original(JSONObject doc)throws Exception{String originalName=doc.optString("originalName","Original Document");int dot=originalName.lastIndexOf('.');String extension=dot>=0?originalName.substring(dot+1):"bin";File out=file(doc,extension.replaceAll("[^A-Za-z0-9]",""));try(OutputStream output=new BufferedOutputStream(new FileOutputStream(out))){output.write(repo.original(doc));}return out;}
 private String picture(int id,long cx,long cy){return "<w:p><w:pPr><w:jc w:val=\"center\"/></w:pPr><w:r><w:drawing><wp:inline><wp:extent cx=\""+cx+"\" cy=\""+cy+"\"/><wp:docPr id=\""+id+"\" name=\"Document page "+id+"\"/><a:graphic><a:graphicData uri=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><pic:pic><pic:nvPicPr><pic:cNvPr id=\""+id+"\" name=\"page"+id+".jpg\"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed=\"rId"+id+"\"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x=\"0\" y=\"0\"/><a:ext cx=\""+cx+"\" cy=\""+cy+"\"/></a:xfrm><a:prstGeom prst=\"rect\"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>";}
 private File file(JSONObject doc,String ext)throws IOException{File dir=new File(c.getCacheDir(),"exports");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Cannot create export folder");String title=doc.optString("title","Document").replaceAll("[^A-Za-z0-9._ -]","_");return new File(dir,title+"."+ext);}
 Uri uri(File f){return FileProvider.getUriForFile(c,c.getPackageName()+".files",f);}
 void open(File f,String mime){Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri(f),mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);c.startActivity(Intent.createChooser(i,"Open Original Document"));}
 void share(File f,String mime){Intent i=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri(f)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);c.startActivity(Intent.createChooser(i,"Share Secure Copy"));}
 void print(android.app.Activity a,File pdf,String name){PrintManager m=(PrintManager)a.getSystemService(Context.PRINT_SERVICE);m.print(name,new PdfFileAdapter(pdf),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setColorMode(PrintAttributes.COLOR_MODE_COLOR).build());}
 private static void put(ZipOutputStream z,String name,String text)throws IOException{bytes(z,name,text.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private static void bytes(ZipOutputStream z,String name,byte[] b)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(b);z.closeEntry();}
 static final class PdfFileAdapter extends PrintDocumentAdapter{final File f;PdfFileAdapter(File f){this.f=f;}@Override public void onLayout(PrintAttributes oldA,PrintAttributes newA,CancellationSignal c,LayoutResultCallback cb,Bundle b){if(c.isCanceled()){cb.onLayoutCancelled();return;}cb.onLayoutFinished(new PrintDocumentInfo.Builder(f.getName()).setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).build(),!newA.equals(oldA));}@Override public void onWrite(android.print.PageRange[] p,android.os.ParcelFileDescriptor d,CancellationSignal c,WriteResultCallback cb){try(InputStream in=new FileInputStream(f);OutputStream out=new FileOutputStream(d.getFileDescriptor())){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){cb.onWriteFailed(e.getMessage());}}}
}
